<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Kanban Board</title>
    <style>
        :root {
            --bg-color: #f4f7f9;
            --column-bg: #ebedf0;
            --card-bg: #ffffff;
            --primary-color: #0079bf;
            --danger-color: #ef5350;
            --text-color: #172b4d;
            --shadow: 0 1px 3px rgba(0,0,0,0.12), 0 1px 2px rgba(0,0,0,0.24);
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-color);
            margin: 0;
            padding: 20px;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        h1 {
            margin-bottom: 20px;
            font-weight: 300;
        }

        /* Input Section */
        .input-area {
            margin-bottom: 30px;
            display: flex;
            gap: 10px;
            width: 100%;
            max-width: 400px;
        }

        #new-card {
            flex-grow: 1;
            padding: 10px;
            border: 2px solid #dfe1e6;
            border-radius: 4px;
            font-size: 1rem;
            outline: none;
        }

        #new-card:focus {
            border-color: var(--primary-color);
        }

        #add-card {
            padding: 10px 20px;
            background-color: var(--primary-color);
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-weight: bold;
            transition: background 0.2s;
        }

        #add-card:hover {
            background-color: #026aa7;
        }

        /* Board Layout */
        #board {
            display: flex;
            gap: 20px;
            width: 100%;
            max-width: 1200px;
            align-items: flex-start;
        }

        .column {
            background-color: var(--column-bg);
            border-radius: 8px;
            width: 33%;
            min-height: 400px;
            display: flex;
            flex-direction: column;
            padding: 10px;
            box-sizing: border-box;
        }

        .column-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 5px 10px 15px 10px;
            font-weight: bold;
            text-transform: uppercase;
            font-size: 0.85rem;
            color: #5e6c84;
        }

        .count {
            background-color: #dfe1e6;
            padding: 2px 8px;
            border-radius: 10px;
            font-size: 0.75rem;
        }

        .card-container {
            flex-grow: 1;
            min-height: 300px; /* Ensures drop target is visible when empty */
        }

        /* Cards */
        .card {
            background-color: var(--card-bg);
            border-radius: 4px;
            padding: 12px;
            margin-bottom: 8px;
            box-shadow: var(--shadow);
            cursor: grab;
            display: flex;
            justify-content: space-between;
            align-items: center;
            word-wrap: break-word;
        }

        .card:active {
            cursor: grabbing;
        }

        .card.dragging {
            opacity: 0.5;
        }

        .card-title {
            flex-grow: 1;
            font-size: 0.95rem;
            margin-right: 10px;
        }

        .card-del {
            background: none;
            border: none;
            color: #a5adb1;
            font-size: 1.2rem;
            cursor: pointer;
            padding: 0 5px;
            line-height: 1;
            transition: color 0.2s;
        }

        .card-del:hover {
            color: var(--danger-color);
        }

        /* Drag Over Visual Feedback */
        .column.drag-over {
            background-color: #dadde2;
            outline: 2px dashed #0079bf;
        }

        @media (max-width: 768px) {
            #board {
                flex-direction: column;
            }
            .column {
                width: 100%;
            }
        }
    </style>
</head>
<body>

    <h1>Kanban Board</h1>

    <div class="input-area">
        <input type="text" id="new-card" placeholder="New task title..." autocomplete="off">
        <button id="add-card">Add</button>
    </div>

    <div id="board">
        <!-- To Do Column -->
        <div id="col-todo" class="column" ondragover="onDragOver(event)" ondragleave="onDragLeave(event)" ondrop="onDrop(event, 'todo')">
            <div class="column-header">
                <span>To Do</span>
                <span class="count">0</span>
            </div>
            <div class="card-container"></div>
        </div>

        <!-- Doing Column -->
        <div id="col-doing" class="column" ondragover="onDragOver(event)" ondragleave="onDragLeave(event)" ondrop="onDrop(event, 'doing')">
            <div class="column-header">
                <span>Doing</span>
                <span class="count">0</span>
            </div>
            <div class="card-container"></div>
        </div>

        <!-- Done Column -->
        <div id="col-done" class="column" ondragover="onDragOver(event)" ondragleave="onDragLeave(event)" ondrop="onDrop(event, 'done')">
            <div class="column-header">
                <span>Done</span>
                <span class="count">0</span>
            </div>
            <div class="card-container"></div>
        </div>
    </div>

    <script>
        // State Management
        let state = [];

        // DOM Elements
        const inputEl = document.getElementById('new-card');
        const addButton = document.getElementById('add-card');
        const columns = {
            todo: document.querySelector('#col-todo .card-container'),
            doing: document.querySelector('#col-doing .card-container'),
            done: document.querySelector('#col-done .card-container')
        };
        const counts = {
            todo: document.querySelector('#col-todo .count'),
            doing: document.querySelector('#col-doing .count'),
            done: document.querySelector('#col-done .count')
        };

        // Initialization
        function init() {
            const savedState = localStorage.getItem('kanban-board-state');
            if (savedState) {
                state = JSON.parse(savedState);
            }
            render();
        }

        function save() {
            localStorage.setItem('kanban-board-state', JSON.stringify(state));
        }

        // Rendering logic
        function render() {
            // Clear all containers
            Object.values(columns).forEach(container => container.innerHTML = '');

            // Reset counts
            Object.values(counts).forEach(countEl => countEl.textContent = '0');

            const colCounts = { todo: 0, doing: 0, done: 0 };

            state.forEach(cardObj => {
                const cardEl = createCardElement(cardObj);
                columns[cardObj.column].appendChild(cardEl);
                colCounts[cardObj.column]++;
            });

            // Update count text
            for (const key in colCounts) {
                counts[key].textContent = colCounts[key];
            }
        }

        function createCardElement(cardObj) {
            const card = document.createElement('div');
            card.className = 'card';
            card.draggable = true;
            card.dataset.id = cardObj.id;

            const titleSpan = document.createElement('span');
            titleSpan.className = 'card-title';
            titleSpan.textContent = cardObj.text;

            const delBtn = document.createElement('button');
            delBtn.className = 'card-del';
            delBtn.innerHTML = '&times;';
            delBtn.onclick = (e) => {
                e.stopPropagation();
                deleteCard(cardObj.id);
            };

            card.appendChild(titleSpan);
            card.appendChild(delBtn);

            // Drag events
            card.addEventListener('dragstart', (e) => {
                e.dataTransfer.setData('text/plain', cardObj.id);
                card.classList.add('dragging');
            });

            card.addEventListener('dragend', () => {
                card.classList.remove('dragging');
            });

            return card;
        }

        // Actions
        function addCard() {
            const text = inputEl.value.trim();
            if (!text) return;

            const newCard = {
                id: 'card-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
                text: text,
                column: 'todo'
            };

            state.push(newCard);
            inputEl.value = '';
            save();
            render();
        }

        function deleteCard(id) {
            state = state.filter(card => card.id !== id);
            save();
            render();
        }

        // Drag and Drop Handlers
        function onDragOver(e) {
            e.preventDefault();
            const column = e.currentTarget;
            column.classList.add('drag-over');
        }

        function onDragLeave(e) {
            e.currentTarget.classList.remove('drag-over');
        }

        function onDrop(e, columnId) {
            e.preventDefault();
            e.currentTarget.classList.remove('drag-over');

            const cardId = e.dataTransfer.getData('text/plain');
            const cardIndex = state.findIndex(c => c.id === cardId);

            if (cardIndex !== -1) {
                state[cardIndex].column = columnId;
                save();
                render();
            }
        }

        // Event Listeners
        addButton.addEventListener('click', addCard);

        inputEl.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') addCard();
        });

        // Boot
        init();

    </script>
</body>
</html>
